{
  "name": "CBox驱动的Transmon超导量子比特",
  "name_en": "CBox-driven transmon qubit",
  "manufacturer": "",
  "description": "一种通过微波脉冲、读出谐振腔和通量脉冲进行控制与测量的Transmon超导量子比特，并配合CBox电子学完成时序与采集。该器件常用于量子计算实验中的能谱测量、Rabi、T1、Ramsey、回波、单次读出、随机基准测试，以及通量脉冲和CZ相关相位表征。",
  "description_en": "A superconducting transmon qubit controlled and measured with microwave pulses, a readout resonator, and flux pulses, using CBox-based electronics for timing and acquisition. It is used in quantum computing experiments for spectroscopy, Rabi, T1, Ramsey, echo, single-shot readout, randomized benchmarking, and characterization of flux pulses and CZ-related phase behavior.",
  "tag_hints": [
    "superconducting qubit",
    "transmon",
    "microwave qubit control",
    "dispersive readout",
    "single-shot readout",
    "flux pulse control",
    "randomized benchmarking",
    "coherence measurements"
  ],
  "actions": [
    {
      "action_name": "auto-add_parameters",
      "description": "定义该Transmon实验所需的时域、读出及混频校准参数。",
      "description_en": "Define time-domain, readout, and mixer-calibration parameters for the transmon experiment."
    },
    {
      "action_name": "auto-upload_qasm_file",
      "description": "上传用于控制该量子比特实验的脉冲序列程序。",
      "description_en": "Upload the pulse-sequence program used to control the qubit experiment."
    },
    {
      "action_name": "auto-prepare_for_continuous_wave",
      "description": "将量子比特与读出链路配置为连续波测量模式。",
      "description_en": "Configure the qubit and readout chain for continuous-wave measurements."
    },
    {
      "action_name": "auto-prepare_readout",
      "description": "配置读出频率、读出脉冲和采集设置。",
      "description_en": "Configure readout frequency, readout pulse, and acquisition settings."
    },
    {
      "action_name": "auto-prepare_for_timedomain",
      "description": "将该Transmon配置为脉冲时域测量模式。",
      "description_en": "Configure the transmon for pulsed time-domain measurements."
    },
    {
      "action_name": "auto-prepare_for_fluxing",
      "description": "配置该量子比特的通量脉冲实验模式。",
      "description_en": "Configure the qubit for flux-pulse experiments."
    },
    {
      "action_name": "auto-calibrate_pulse_restless",
      "description": "用restless方法校准量子比特控制脉冲的幅度、Motzoi参数和频率。",
      "description_en": "Calibrate qubit control-pulse amplitude, Motzoi parameter, and frequency using a restless method."
    },
    {
      "action_name": "auto-calibrate_mixer_offsets_drive",
      "description": "校准驱动链路I/Q混频器的直流偏置。",
      "description_en": "Calibrate the DC offsets of the drive-path I/Q mixer."
    },
    {
      "action_name": "auto-calibrate_mixer_offsets_RO",
      "description": "校准读出链路I/Q混频器的直流偏置。",
      "description_en": "Calibrate the DC offsets of the readout-path I/Q mixer."
    },
    {
      "action_name": "auto-calibrate_mixer_skewness",
      "description": "校准I/Q混频器的幅相不平衡与偏斜。",
      "description_en": "Calibrate I/Q mixer imbalance and skew."
    },
    {
      "action_name": "auto-calibrate_MW_RO_latency",
      "description": "校准微波控制脉冲与读出脉冲之间的时延。",
      "description_en": "Calibrate the timing delay between microwave control and readout pulses."
    },
    {
      "action_name": "auto-measure_heterodyne_spectroscopy",
      "description": "进行外差频谱测量以表征量子比特或读出谐振腔响应。",
      "description_en": "Perform heterodyne spectroscopy to characterize the qubit or readout-resonator response."
    },
    {
      "action_name": "auto-measure_spectroscopy",
      "description": "测量量子比特频谱响应。",
      "description_en": "Measure the qubit spectroscopy response."
    },
    {
      "action_name": "auto-measure_pulsed_spectroscopy",
      "description": "进行脉冲式量子比特频谱测量。",
      "description_en": "Perform pulsed qubit spectroscopy."
    },
    {
      "action_name": "auto-measure_resonator_power",
      "description": "测量读出谐振腔对频率和激励功率的响应。",
      "description_en": "Measure the readout resonator response versus frequency and probe power."
    },
    {
      "action_name": "auto-measure_resonator_dac",
      "description": "测量读出谐振腔对频率和DAC驱动设置的响应。",
      "description_en": "Measure the readout resonator response versus frequency and DAC drive setting."
    },
    {
      "action_name": "auto-measure_rabi",
      "description": "测量Rabi振荡以标定驱动脉冲强度。",
      "description_en": "Measure Rabi oscillations to calibrate drive-pulse strength."
    },
    {
      "action_name": "auto-measure_motzoi",
      "description": "测量控制脉冲对Motzoi参数的依赖，用于DRAG类校准。",
      "description_en": "Measure control-pulse dependence on the Motzoi parameter for DRAG-style calibration."
    },
    {
      "action_name": "auto-measure_randomized_benchmarking",
      "description": "通过随机基准测试测量单量子比特门保真度。",
      "description_en": "Measure single-qubit gate fidelity using randomized benchmarking."
    },
    {
      "action_name": "auto-measure_randomized_benchmarking_vs_pars",
      "description": "测量随机基准测试结果随控制参数变化的关系。",
      "description_en": "Measure randomized-benchmarking performance versus control parameters."
    },
    {
      "action_name": "auto-measure_T1",
      "description": "测量量子比特的能量弛豫时间T1。",
      "description_en": "Measure the qubit energy-relaxation time T1."
    },
    {
      "action_name": "auto-measure_ramsey",
      "description": "测量Ramsey条纹以表征失相干与频率偏移。",
      "description_en": "Measure Ramsey fringes to characterize dephasing and frequency detuning."
    },
    {
      "action_name": "auto-measure_echo",
      "description": "测量回波序列以表征相干时间。",
      "description_en": "Measure an echo sequence to characterize coherence time."
    },
    {
      "action_name": "auto-measure_allxy",
      "description": "执行AllXY序列以校准单量子比特门操作。",
      "description_en": "Perform the AllXY sequence to calibrate single-qubit gate operations."
    },
    {
      "action_name": "auto-measure_flipping",
      "description": "测量重复翻转序列，以评估π脉冲精度和失谐效应。",
      "description_en": "Measure repeated flipping sequences to assess pi-pulse accuracy and detuning effects."
    },
    {
      "action_name": "auto-measure_ssro",
      "description": "测量单次读出性能与态判别能力。",
      "description_en": "Measure single-shot readout performance and state-discrimination capability."
    },
    {
      "action_name": "auto-measure_transients",
      "description": "测量量子比特处于不同状态时的读出瞬态响应。",
      "description_en": "Measure readout transients for different qubit states."
    },
    {
      "action_name": "auto-calibrate_optimal_weights",
      "description": "校准读出判别所需的最佳积分权重。",
      "description_en": "Calibrate optimal integration weights for readout discrimination."
    },
    {
      "action_name": "auto-measure_butterfly",
      "description": "测量butterfly读出实验以评估初始化与读出相关性。",
      "description_en": "Perform a butterfly readout experiment to assess initialization and readout correlations."
    },
    {
      "action_name": "auto-measure_rb_vs_amp",
      "description": "测量随机基准测试结果随驱动幅度的变化。",
      "description_en": "Measure randomized-benchmarking performance versus drive amplitude."
    },
    {
      "action_name": "auto-calibrate_Flux_pulse_latency",
      "description": "校准通量脉冲相对于微波控制和读出的时延。",
      "description_en": "Calibrate the timing delay of flux pulses relative to microwave control and readout."
    },
    {
      "action_name": "auto-measure_flux_timing",
      "description": "测量通量脉冲与微波脉冲之间的相对时序。",
      "description_en": "Measure the relative timing between flux pulses and microwave pulses."
    },
    {
      "action_name": "auto-measure_ram_z",
      "description": "测量通量脉冲长度引起的相位累积（Ram-Z实验）。",
      "description_en": "Measure phase accumulation versus flux-pulse length in a Ram-Z experiment."
    },
    {
      "action_name": "auto-measure_cryo_scope",
      "description": "通过量子比特响应表征通量脉冲波形的时间演化。",
      "description_en": "Characterize the time evolution of a flux-pulse waveform through the qubit response."
    },
    {
      "action_name": "auto-measure_ram_z_echo",
      "description": "测量带回波的通量诱导相位累积。",
      "description_en": "Measure flux-induced phase accumulation using an echo-based sequence."
    },
    {
      "action_name": "auto-measure_CZ_phase_ripple",
      "description": "测量CZ类通量脉冲相关的相位起伏与附加相位。",
      "description_en": "Measure phase ripple and accumulated phase associated with CZ-type flux pulses."
    },
    {
      "action_name": "auto-get_operation_dict",
      "description": "定义该Transmon实验可用的微波、通量、频谱和读出操作集合。",
      "description_en": "Define the available microwave, flux, spectroscopy, and readout operations for the transmon experiment."
    },
    {
      "action_name": "auto-measure_single_qubit_GST",
      "description": "测量单量子比特门集层析以完整表征门操作。",
      "description_en": "Perform single-qubit gate set tomography to fully characterize gate operations."
    },
    {
      "action_name": "auto-load_QWG_pulses",
      "description": "将控制或通量脉冲波形加载到波形发生器中用于量子比特实验。",
      "description_en": "Load control or flux-pulse waveforms into the waveform generator for the qubit experiment."
    }
  ]
}

